async def check_update(dev: Device, internet: bool, update: bool):
    """Print out update information."""
    if not update:
        return
    if dev.update_available:
        if internet:
            print(f"{dev.name} has an update available.")
        else:
            print(f"{dev.name} has an update available. Please connect to the internet to check for updates.")
    else:
        if internet:
            print(f"{dev.name} is up to date.")
        else:
            print(f"{dev.name} is up to date. Please connect to the internet to check for updates.")

